function normalizarNome(nome: string) {
  return nome
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
}

function obterFotoPorNome(fotosUsuarios: { [nome: string]: string }, nome: string) {
  if (fotosUsuarios[nome]) return fotosUsuarios[nome];

  const nomeNormalizado = normalizarNome(nome);
  const chaveFoto = Object.keys(fotosUsuarios).find(chave => {
    const chaveNormalizada = normalizarNome(chave);
    return (
      chaveNormalizada === nomeNormalizado ||
      nomeNormalizado.includes(chaveNormalizada) ||
      chaveNormalizada.includes(nomeNormalizado)
    );
  });

  return chaveFoto ? fotosUsuarios[chaveFoto] : undefined;
}

